const COMMON_HEADERS = {
  'X-Content-Type-Options': 'nosniff',
  'Referrer-Policy': 'strict-origin-when-cross-origin',
  'X-Frame-Options': 'DENY',
};
const INFO = {
  name: 'Simdentia',
  location: '66 Poath Road, Hughesdale VIC 3166',
  acn: '703 933 411',
  status: 'Opening soon',
  stationType: 'Dedicated dental simulation station',
  sessions: [{name:'Morning',start:'09:00',end:'15:00'}, {name:'Afternoon',start:'15:00',end:'21:00'}],
  currency: 'AUD',
  standardPricePerChairPerSession: 120,
  openingMonthPricePerChairPerSession: 100,
  booking: 'Contact via Instagram, Facebook, phone or email. No online payment or checkout.',
};
export default {
  async fetch(request, env = {}) {
    const url = new URL(request.url);
    const path = url.pathname;
    const method = request.method;
    if (method !== 'GET' && method !== 'HEAD') {
      return new Response('Method not allowed', {status:405,headers:{...COMMON_HEADERS,'Allow':'GET, HEAD'}});
    }
    const head = method === 'HEAD';
    if (path === '/' || path === '/index.html') {
      return new Response(head ? null : buildHtml(env), {
        status:200,
        headers:{...COMMON_HEADERS,'Content-Type':'text/html; charset=utf-8', 'Cache-Control':'no-store', 'X-Simdentia-Worker':'dynamic'},
      });
    }
    const policyAliases = {'/privacy-policy':'/privacy','/terms-of-service':'/terms','/refund-policy':'/refunds','/refund':'/refunds','/cookie-policy':'/cookies','/data-deletion':'/data-requests'};
    const policyPath = policyAliases[path] || path;
    if (POLICY_PAGES[policyPath]) {
      return new Response(head ? null : renderPolicyPage(policyPath), {status:200,headers:{...COMMON_HEADERS,'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store'}});
    }
    if (path === '/api/info') {
      const payload = {...INFO, timestamp: new Date().toISOString(),
        instagram: 'https://www.instagram.com/simdentia.au/',
        facebook: env.SIMDENTIA_FACEBOOK || FACEBOOK_DEFAULT,
        phone: env.SIMDENTIA_PHONE || null,
        email: env.SIMDENTIA_EMAIL || EMAIL_DEFAULT};
      return new Response(head ? null : JSON.stringify(payload), {
        headers:{...COMMON_HEADERS,'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store'},
      });
    }
    if (path === '/health') {
      return new Response(head ? null : 'OK — Simdentia Cloudflare Worker',{
        headers:{...COMMON_HEADERS,'Content-Type':'text/plain; charset=utf-8','Cache-Control':'no-store'},
      });
    }
    const file = IMAGE_ASSETS[path];
    if (file) return new Response(head ? null : bytesFromBase64(file.base64), {
      headers:{...COMMON_HEADERS,'Content-Type':file.type,'Cache-Control':path.startsWith('/assets/') ? 'public, max-age=31536000, immutable' : 'public, max-age=2592000'},
    });
    const textFile = TEXT_ASSETS[path];
    if (textFile) return new Response(head ? null : textFile.body, {
      headers:{...COMMON_HEADERS,'Content-Type':textFile.type,'Cache-Control':'public, max-age=3600'},
    });
    return new Response(head ? null : '<!doctype html><html lang="en"><head><meta name="viewport" content="width=device-width, initial-scale=1"><title>Page not found · Simdentia</title></head><body style="font-family:system-ui;text-align:center;margin:15vh auto;max-width:650px;padding:20px"><h1>Page not found</h1><p>The address you entered does not exist.</p><p><a href="/">Return to Simdentia home</a></p></body></html>',{
      status:404,headers:{...COMMON_HEADERS,'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store'},
    });
  },
};
